    if len(sys.argv) == 4 and sys.argv[1] == "--hook-fault-probe":
        raise SystemExit(_hook_fault_probe_main(sys.argv[2], sys.argv[3]))
    raise SystemExit("required_ci_candidate.py is a trusted support module")
